/* ============================================= 
        design
============================================= */
.chat_box {
    width: fit-content;
    min-width: 380px;
    max-width: calc(100% - 40px);   
    position: relative;
}

.chat_box::before, .chat_box::after {
    content: "";
    position: absolute;
    z-index: 2;
    background-position: center;
    background-repeat: no-repeat;
    background-size: 100%;
}

.chat_box::before {
    width: 34px;
    height: 39px;
    left: -12px;
    top: 8px;
    background: var(--snowL);
}

.chat_box::after {
    width: 37.5px;
    height: 38.5px;
    right: -10px;
    top: -13px;
    background: var(--snowR);
}

.chat_box .inner_box {
    position: relative;
    padding: 25px 48px;
    background: 
    var(--Bline) repeat-x,
    var(--prism) no-repeat,
    var(--pattern) repeat,
    var(--back) repeat,
    var(--outline) repeat;
    background-size: 704px, 643px, 470px, cover, cover;
    background-position: center bottom 8px, top -154px left -158px, center, center;
    background-blend-mode: normal, color-dodge, normal, normal, normal;
    background-clip: padding-box, padding-box, padding-box, padding-box, border-box;
    border: 2px solid transparent;
    box-shadow: var(--inshadow);
}

.chat_box .inner_box::before {
    content: "";
    position: absolute;
    inset: 4px 2px 4px 2px;
    background: var(--dividerL), var(--dividerR);
    background-size: 136px, 100px;
    background-repeat: no-repeat, no-repeat;
    background-position: left -22px bottom -320px, right -5px top -268px;
}

.chat_box .inner_box .name {
    width: fit-content;
    position: absolute !important;
    background: var(--nback);
    border: var(--nbor);
    outline: var(--nout);
    top: -15px;
    left: 50%;
    transform: translateX(-50%);
    border-radius: 999vh;
    font-size: 16px !important;
    padding: 2px 20px;
    font-weight: 400 !important;
}

.chat_box .inner_box .text {
    background: var(--text);
    background-clip: text;
    -webkit-background-clip: text;
    color: transparent !important;
    filter: contrast(120%) saturate(130%);
}

