/* ============================================= 
        keyframes
============================================= */
@keyframes winter-popup-elegant {
    0% {
        opacity: 0;
        transform: translate3d(0, 14px, 0);
        filter: blur(4px);
    }

    100% {
        opacity: 1;
        transform: translate3d(0, 0, 0);
        filter: blur(0);
    }
}

@keyframes winter-divider-curtain {
    0% {
        opacity: 0;
        -webkit-clip-path: inset(50% 0 50% 0);
        clip-path: inset(50% 0 50% 0);
        -webkit-mask-size: 100% 6%;
        mask-size: 100% 6%;
        filter: blur(3px);
    }

    100% {
        opacity: 1;
        -webkit-clip-path: inset(0 0 0 0);
        clip-path: inset(0 0 0 0);
        -webkit-mask-size: 100% 100%;
        mask-size: 100% 100%;
        filter: blur(0);
    }
}

@keyframes winter-name-fade {
    0% {
        opacity: 0;
        transform: translateX(-50%) translateY(-8px);
        filter: blur(2.5px);
    }

    100% {
        opacity: 1;
        transform: translateX(-50%) translateY(0);
        filter: blur(0);
    }
}

@keyframes winter-content-fade {
    0% {
        opacity: 0;
        transform: translateY(7px);
        filter: blur(2.5px);
    }

    100% {
        opacity: 1;
        transform: translateY(0);
        filter: blur(0);
    }
}

@keyframes winter-snow-left-fade {
    0% {
        opacity: 0;
        transform: translate(-8px, 5px) rotate(-8deg);
        filter: blur(2px);
    }

    100% {
        opacity: 1;
        transform: translate(0, 0) rotate(0);
        filter: blur(0);
    }
}

@keyframes winter-snow-right-fade {
    0% {
        opacity: 0;
        transform: translate(8px, -5px) rotate(8deg);
        filter: blur(2px);
    }

    100% {
        opacity: 1;
        transform: translate(0, 0) rotate(0);
        filter: blur(0);
    }
}



@keyframes winter-gloss-sweep-visible {
    0%,
    12% {
        opacity: 0;
        background-position: 100% 50%;
    }

    18% {
        opacity: 0.34;
    }

    27% {
        opacity: 0.96;
    }

    48% {
        opacity: 0.72;
        background-position: 0% 50%;
    }

    55%,
    100% {
        opacity: 0;
        background-position: 0% 50%;
    }
}

/* =============================================
        animation declarations
============================================= */
.chat_box {
    transform-origin: center center;
    animation: winter-popup-elegant 740ms cubic-bezier(0.22, 0.72, 0.24, 1) both !important;
}

.chat_box .inner_box::before {
    transform-origin: center center;
    -webkit-mask-image: linear-gradient(
        to bottom,
        transparent 0%,
        #000 7%,
        #000 93%,
        transparent 100%
    );
    mask-image: linear-gradient(
        to bottom,
        transparent 0%,
        #000 7%,
        #000 93%,
        transparent 100%
    );
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    -webkit-mask-position: center;
    mask-position: center;
    will-change: clip-path, mask-size, opacity, filter;
    animation: winter-divider-curtain 1180ms cubic-bezier(0.22, 0.72, 0.24, 1) 900ms both;
}

.chat_box .inner_box .name {
    animation: winter-name-fade 580ms cubic-bezier(0.22, 0.72, 0.24, 1) 210ms both;
}

.chat_box .inner_box > *:not(.name) {
    animation: winter-content-fade 610ms cubic-bezier(0.22, 0.72, 0.24, 1) 160ms both;
}

.chat_box::before {
    transform-origin: center center;
    animation: winter-snow-left-fade 640ms cubic-bezier(0.22, 0.72, 0.24, 1) 110ms both;
}

.chat_box::after {
    transform-origin: center center;
    animation: winter-snow-right-fade 640ms cubic-bezier(0.22, 0.72, 0.24, 1) 145ms both;
}

.chat_box .inner_box::after {
    content: "";
    position: absolute;
    inset: 2px;
    z-index: 2;
    pointer-events: none;
    border-radius: inherit;

    background:
        linear-gradient(
            112deg,
            transparent 0%,
            transparent 34%,
            rgba(176, 185, 255, 0.08) 40%,
            rgba(145, 208, 255, 0.25) 44%,
            rgba(215, 239, 255, 0.52) 48%,
            rgba(255, 255, 255, 0.82) 50%,
            rgba(231, 216, 255, 0.40) 53%,
            rgba(159, 204, 255, 0.20) 58%,
            transparent 65%,
            transparent 100%
        );

    background-size: 360% 100%;
    background-position: 100% 50%;
    background-repeat: no-repeat;

    -webkit-mask-image: linear-gradient(
        to bottom,
        transparent 0%,
        #000 12%,
        #000 88%,
        transparent 100%
    );
    mask-image: linear-gradient(
        to bottom,
        transparent 0%,
        #000 12%,
        #000 88%,
        transparent 100%
    );

    filter: blur(0.15px) saturate(118%);
    will-change: background-position, opacity;
    animation: winter-gloss-sweep-visible 8s cubic-bezier(0.22, 0.66, 0.28, 1) 600ms infinite;
}

.chat_box.image.subscribe .inner_box::after {
    background-image:
        linear-gradient(
            112deg,
            transparent 0%,
            transparent 34%,
            rgba(255, 241, 211, 0.03) 40%,
            rgba(255, 230, 184, 0.10) 44%,
            rgba(255, 244, 218, 0.22) 48%,
            rgba(255, 255, 249, 0.58) 50%,
            rgba(255, 239, 205, 0.18) 53%,
            rgba(226, 203, 155, 0.07) 58%,
            transparent 65%,
            transparent 100%
        );
    filter: blur(0.15px) saturate(108%);
}

